sys_script_include.script:
var InvoiceDateHelfer = Class.create();
InvoiceDateHelfer.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getAvailableYearsAndMonths: function() {
        var userName = this.getParameter('sysparm_userName');

        var result = {
            years: [],
            dates: {}
        };

        gs.info('Received username: ' + userName);

        // Query to get the user record
        var userGR = new GlideRecord('sys_user');
        userGR.addQuery('user_name', userName);
        userGR.query();

        if (!userGR.next()) {
            gs.info('No user found with username: ' + userName);
            return JSON.stringify(result);
        }

        var companySysId = userGR.getValue('company');
        gs.info('Retrieved company sys_id: ' + companySysId);

        if (!companySysId) {
            gs.info('No company sys_id found for user: ' + userName);
            return JSON.stringify(result);
        }

        // Query to get invoices for the user's company
        var gr = new GlideRecord('x_sigh_a_a_portal_invoices');
        gr.addQuery('company', companySysId);
        gr.query();

        if (!gr.hasNext()) {
            gs.info('No records found for company sys_id: ' + companySysId);
            return JSON.stringify(result);
        }

        var years = {};
        var dates = {};

        gs.info('Start processing invoices for company sys_id: ' + companySysId);

        while (gr.next()) {
            var date = new GlideDateTime(gr.getValue('date'));
            var year = date.getYearLocalTime();
            var month = date.getMonthLocalTime(); // Monat direkt verwenden
            var day = date.getDayOfMonthLocalTime();

			/*switch(month){
				case 1:
					month = 'Januar';
					break;
				case 2:
					month = 'Februar';
					break;	
				case 3:
					month = 'Maerz';
					break;
				case 4:
					month = 'April';
					break;	
				case 5:
					month = 'Mai';
					break;	
				case 6:
					month = 'Juni';
					break;	
				case 7:
					month = 'Juli';
					break;
				case 8:
					month = 'August';
					break;
				case 9:
					month = 'September';
					break;
				case 10:
					month = 'Oktober';
					break;	
				case 11:
					month = 'November';
					break;
				case 12:
					month = 'Dezember';
					break;				

			}*/
            const MONTH_NAMES = [
                "Januar", "Februar", "März", "April", "Mai", "Juni",
                "Juli", "August", "September", "Oktober", "November", "Dezember"
            ];
            month = MONTH_NAMES[month-1]

            years[year] = true;
            if (!dates[year]) {
                dates[year] = [];
            }
            dates[year].push(month + ' ' + year); // Datum im Format 'Monat Jahr' speichern
        }

        result.years = Object.keys(years).sort();
        for (var y in dates) {
            result.dates[y] = Array.from(new Set(dates[y])).sort(function(a, b) {
                // Sortiere nach Datum im Format 'Tag.Monat.Jahr'
                var aParts = a.split('.').map(Number);
                var bParts = b.split('.').map(Number);
                return new Date(aParts[2], aParts[1] - 1, aParts[0]) - new Date(bParts[2], bParts[1] - 1, bParts[0]);
            });
        }

        gs.info('Final years: ' + JSON.stringify(result.years));
        gs.info('Final dates: ' + JSON.stringify(result.dates));

        return JSON.stringify(result);
    },

    type: 'InvoiceDateHelfer'
});
